function salesError(error,form){const region=form?.querySelector('.form-error');if(region){region.innerHTML=esc(error.message)+(error.status===409?`<div class="form-actions">${button('Reload sales records','reload-sales','small')}</div>`:'');}else toast(error.message);}
async function salesCorrection(el){
  const action=el.dataset.action;if(action==='edit-activity'){activityEditor(el.dataset.id);return;}if(action==='edit-target'){targetEditor(el.dataset.id);return;}
  if(action==='reload-sales'){if(dialog.open&&dirtyDialog()&&!confirm('Discard your unsaved correction and reload the latest sales records?'))return;state.sales=await api('/sales');dialog.close();render();return;}
  if(action==='delete-activity'){
    const record=state.sales?.activities.find(a=>a.id===el.dataset.id);if(!record||!canCorrectActivity(record))throw new Error('This activity is not available for deletion.');
    if(!confirm('Delete this activity for '+record.context+'? It will leave activity totals; its audit history is retained.'))return;
    try{state.sales=await api('/sales/activities/'+encodeURIComponent(record.id),'DELETE',{expectedVersion:Number(el.dataset.version)});dialog.close();render();toast('Activity deleted. Totals updated.');}catch(error){salesError(error,el.closest('form'));}
  }
}
async function action(el){const a=el.dataset.action;if(['edit-activity','delete-activity','edit-target','reload-sales'].includes(a)){await salesCorrection(el);return;}if(a==='retry-route'){await navigate();return;}if(a==='logout'){if(hasUnsavedWork()&&!confirm('Sign out and discard your unsaved changes?'))return;await api('/auth/logout','POST',{});await signedOut();return;}if(a==='load-more'){await loadTasks(true);render();return;}if(a==='delete-task'){if(!confirm('Move this task to deleted records? The founder can restore it later.'))return;await api(`/tasks/${state.task.id}`,'DELETE',{expectedVersion:state.task.version});dialog.close();state.task=null;await afterTask('Task moved to deleted records');return;}if(a==='deleted-tasks'){const records=await api('/tasks/deleted');openDialog('Deleted tasks',records.map(t=>`<div class="data-row"><div><h3>${esc(t.title)}</h3><small>Deleted ${timestamp(t.deleted_at)}</small></div>${button('Restore','restore-task','small',`data-id="${t.id}"`)}</div>`).join('')||empty('No deleted tasks'));return;}if(a==='restore-task'){await api(`/tasks/${el.dataset.id}/restore`,'POST',{});dialog.close();await afterTask('Task restored');return;}if(a==='reload-task'){if(dirtyTask()&&!confirm('Discard your unsaved changes and load the latest saved task?'))return;await openTask(state.task.id);return;}if(a==='close-dialog'){if(dirtyDialog()&&!confirm('Discard your unsaved changes?'))return;dialog.close();state.task=null;return;}if(a==='menu'){state.menu=!state.menu;render();if(state.menu)document.querySelector('.sidebar .nav-link')?.focus();else document.getElementById?.('mobile-menu-trigger')?.focus();return;}if(a==='create-task'){state.task=null;createTask(el.dataset.section,el.dataset.status);return;}if(a==='open-task'){await openTask(el.dataset.id);return;}if(a==='tab'){if(state.view==='tasks')state.studio=el.dataset.value==='studio';else state.tab=el.dataset.value;await loadTasks();if(state.view==='academy'&&state.tab==='manage')await academyAdmin.load();render();return;}if(a==='view-mode'){state.mode=el.dataset.value;render();return;}if(a==='archive-filter'){state.archived=!state.archived;await loadTasks();render();return;}if(a==='archive-task'){await changeTask(state.task.id,state.task.version,{archived:!state.task.archived});dialog.close();state.task=null;await afterTask('Task '+(state.archived?'restored':'archived'));return;}if(a==='area'){state.area=el.dataset.value;render();return;}if(a==='course'){const generation=++state.routeVersion,actor=state.data.actor.id;const course=await api(`/courses/${el.dataset.id}`);if(generation!==state.routeVersion||actor!==state.data?.actor?.id)return;state.view='academy';if(location.hash!=='#academy')history.replaceState(null,'','#academy');state.course=course;state.lesson=Math.max(0,state.course.lessons.findIndex(l=>!l.completed_at));render();return;}if(a==='back-courses'){state.course=null;await refresh();render();return;}if(a==='lesson'||a==='next-lesson'){state.lesson=a==='lesson'?Number(el.dataset.index):state.lesson+1;render();return;}if(a==='reopen-lesson'){const generation=state.routeVersion,actor=state.data.actor.id;const course=await api(`/lessons/${el.dataset.id}/progress`,'POST',{completed:false,course_id:state.course.id,course_version:state.course.version});if(generation!==state.routeVersion||actor!==state.data?.actor?.id)return;state.course=course;await refresh();render();toast('Lesson reopened. Completion history retained.');return;}if(a==='complete-lesson'){const generation=state.routeVersion,actor=state.data.actor.id;const course=await api(`/lessons/${el.dataset.id}/complete`,'POST',{});if(generation!==state.routeVersion||actor!==state.data?.actor?.id)return;state.course=course;await refresh();render();toast(state.course.completion?'Course completed. Your record is saved.':'Lesson completed. Progress saved.');return;}if(['activity','report','target'].includes(a)){salesForm(a);return;}if(a==='review-report'){state.sales=await api(`/sales/reports/${el.dataset.id}/review`,'POST',{});render();toast('Report reviewed');return;}if(a==='resource'){const r=state.resources.find(r=>r.id===el.dataset.id);openDialog(r.title,`<span class="eyebrow">${esc(r.kind)} · Internal guidance</span><hr class="rule"><div class="prose">${esc(r.body)}</div>`);return;}if(a==='project'){const p=state.projects.find(p=>p.id===el.dataset.id);openDialog(p.title,`<span class="eyebrow">Project brief</span><hr class="rule"><p>${esc(p.description)}</p><hr class="rule"><div class="spread">${badge(p.status)}<small>Due ${date(p.due_date)}</small></div>`);return;}if(a==='inbox'){const n=await api('/notifications');openDialog('Notifications',n.map(v=>`<div class="data-row"><div><p>${esc(v.body)}</p><small>${timestamp(v.created_at)}</small></div><button class="icon-btn" data-action="open-task" data-id="${v.task_id}" aria-label="Open related task">${icon('arrow')}</button></div>`).join('')||empty('You’re up to date','New task assignments will appear here.'));state.data.notifications=await api('/notifications/read','POST',{});render();}}
document.addEventListener('click',async e=>{if(e.target.closest('.skip')){e.preventDefault();document.querySelector('#main')?.focus({preventScroll:true});return;}const el=e.target.closest('[data-action]');if(!el)return;e.preventDefault();const key=el.dataset.action+':'+(el.dataset.id||'');if(pending.has(key))return;pending.add(key);const returnKey=focusKey(el);el.disabled=true;try{await action(el);}catch(error){toast(error.message);}finally{pending.delete(key);el.disabled=false;if(!dialog.open&&state.data)restoreFocus(returnKey);}});
document.addEventListener('submit',async e=>{const form=e.target;if(!form.dataset.form)return;e.preventDefault();if(form.dataset.pending)return;form.dataset.pending='1';const values=Object.fromEntries(new FormData(form)),submit=form.querySelector('[type=submit]');const submitFocus=focusKey(submit);if(submit)submit.disabled=true;const errorEl=form.querySelector('.form-error');if(errorEl)errorEl.textContent='';try{switch(form.dataset.form){case'create-task':{form.dataset.requestKey ||= globalThis.crypto?.randomUUID?.()||('task_'+Date.now()+'_'+Math.random().toString(36).slice(2));const created=await api('/tasks','POST',values,{'Idempotency-Key':form.dataset.requestKey});dialog.close();await afterTask('Task created');if(created?.id)await openTask(created.id);break;}case'edit-task':{if(!founder()){delete values.owner_id;delete values.section;}await changeTask(state.task.id,state.task.version,values);await afterTask();break;}case'comment':{const draft=taskDraft();if(draft)draft.__commentDraft='';state.task=await api(`/tasks/${state.task.id}/comments`,'POST',values);taskDialog(draft);toast('Comment saved');break;}case'subtask':{const draft=taskDraft();if(draft)draft.__subtaskDraft='';state.task=await api(`/tasks/${state.task.id}/subtasks`,'POST',values);taskDialog(draft);toast('Subtask added');break;}case'activity-edit':state.sales=await api('/sales/activities/'+encodeURIComponent(form.dataset.id),'PATCH',{expectedVersion:Number(form.dataset.version),changes:values});dialog.close();render();toast('Activity corrected. Totals updated.');break;case'activity':form.dataset.requestKey ||= globalThis.crypto?.randomUUID?.()||('activity_'+Date.now()+'_'+Math.random().toString(36).slice(2));state.sales=await api('/sales/activities','POST',values,{'Idempotency-Key':form.dataset.requestKey});dialog.close();render();toast('Activity saved');break;case'report':state.sales=await api('/sales/reports','POST',values);dialog.close();render();toast('Report submitted');break;case'target':values.target=Number(values.target);if(form.dataset.id){values.expectedVersion=Number(form.dataset.version);}else if(state.sales?.targets.some(t=>t.owner_id===values.owner_id&&t.metric===values.metric&&t.period===values.period)){throw new Error('A target already exists for this member, metric and month. Close this form and use Edit target.');}state.sales=await api('/sales/targets','POST',values);dialog.close();render();toast('Target saved');break;}}catch(error){if(['activity-edit','target'].includes(form.dataset.form))salesError(error,form);else if(errorEl)errorEl.textContent=error.message;else toast(error.message);}finally{delete form.dataset.pending;if(submit)submit.disabled=false;if(dialog.open)restoreFocus(submitFocus);}});
document.addEventListener('change',async e=>{const el=e.target;try{if(el.dataset.complete){if(el.disabled)return;el.disabled=true;const t=state.data.tasks.find(t=>t.id===el.dataset.complete);try{await changeTask(t.id,t.version,{status:el.checked?'Done':'Todo'});await afterTask();}catch(error){el.checked=!el.checked;throw error;}finally{el.disabled=false;}}else if(el.dataset.subtask){el.disabled=true;const draft=taskDraft();try{state.task=await api(`/tasks/${state.task.id}/subtasks`,'POST',{id:el.dataset.subtask,completed:el.checked});taskDialog(draft);}catch(error){el.checked=!el.checked;throw error;}finally{el.disabled=false;}}else if(el.id.startsWith('filter-')){state[el.id.slice(7)]=el.value;await loadTasks();render();}else if(el.name==='section'&&el.closest('form')){const owner=el.closest('form').elements.owner_id,old=owner.value;owner.innerHTML=options(ownerOptions(el.value),old);}}catch(error){toast(error.message);}});
document.addEventListener('input',e=>{if(e.target.id==='task-search'){state.search=e.target.value;clearTimeout(searchTimer);searchTimer=setTimeout(async()=>{try{await loadTasks();render();}catch(error){toast(error.message);}},250);}});
document.addEventListener('dragstart',e=>{const card=e.target.closest('.task-card');if(card)e.dataTransfer.setData('text/plain',card.dataset.id);});
document.addEventListener('dragover',e=>{const col=e.target.closest('[data-drop]');if(col){e.preventDefault();col.classList.add('drag-over');}});
document.addEventListener('dragleave',e=>{const col=e.target.closest('[data-drop]');if(col&&!col.contains(e.relatedTarget))col.classList.remove('drag-over');});
document.addEventListener('drop',async e=>{const col=e.target.closest('[data-drop]');if(!col)return;e.preventDefault();col.classList.remove('drag-over');const t=state.data.tasks.find(t=>t.id===e.dataTransfer.getData('text/plain'));if(t&&!pending.has('task-write:'+t.id))try{pending.add('task-write:'+t.id);await changeTask(t.id,t.version,{status:col.dataset.drop});await afterTask('Task moved');}catch(error){toast(error.message);}finally{pending.delete('task-write:'+t.id);}});
function bindDialog(){if(boundDialogs.has(dialog))return;boundDialogs.add(dialog);dialog.addEventListener('cancel',e=>{if(dirtyDialog()&&!confirm('Discard your unsaved changes?'))e.preventDefault();});dialog.addEventListener('close',()=>{state.task=null;restoreFocus(dialogReturn);dialogReturn=null;});}
window.addEventListener('resize',()=>{const sidebar=document.getElementById?.('studio-navigation');if(sidebar)sidebar.inert=!!window.matchMedia?.('(max-width: 700px)').matches&&!state.menu;});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&state.menu&&!dialog.open){state.menu=false;render();document.getElementById?.('mobile-menu-trigger')?.focus();}});
window.addEventListener('hashchange',()=>navigate().catch(e=>toast(e.message)));
function hasUnsavedWork(){return !!state.data&&(!!academyAdmin.hasUnsavedChanges?.()||!!dialog?.open&&dirtyDialog());}
window.addEventListener('beforeunload',event=>{if(!hasUnsavedWork())return;event.preventDefault();event.returnValue='';});
export function unmountWorkspace(){
  mountedHost=null;mountPromise=null;state.routeVersion++;state.taskRequestVersion=(state.taskRequestVersion||0)+1;
  requestController.abort();clearTimeout(toastTimer);clearTimeout(searchTimer);pending.clear();
  state.data=null;state.task=null;state.course=null;academyAdmin.reset();securityUI.reset();connectedSales.reset();
  if(dialog?.open)dialog.close();dialogReturn=null;
}
export async function mountWorkspace(){
  const host=document.querySelector('#app'),nextDialog=document.querySelector('#dialog');
  if(!host||!nextDialog)throw new Error('The workspace scaffold is unavailable.');
  if(mountedHost===host&&mountPromise)return mountPromise;
  unmountWorkspace();app=host;dialog=nextDialog;mountedHost=host;requestController=new AbortController();bindDialog();
  const version=state.routeVersion;
  mountPromise=(async()=>{try{await refresh();if(mountedHost===host&&version===state.routeVersion)await navigate();}
    catch(error){if(mountedHost!==host||error.name==='AbortError')return;
      if(error.status===401)await signedOut();
      else app.innerHTML=`<main id="main" class="production-access-state" tabindex="-1"><h1>The workspace could not open.</h1><p role="alert">${esc(error.message)}</p><p>Reload this page. If the problem continues, contact the workspace owner.</p><button type="button" class="button primary" data-action="reload-workspace">Reload workspace</button></main>`;
    }})();return mountPromise;
}
document.addEventListener('click',event=>{if(event.target.closest('[data-action="reload-workspace"]')){event.preventDefault();window.location.reload();}});
